local zones = {
	[947] = {
		name = "Azeroth",
		short = "Há dez mil anos, os Altaneiros de Kalimdor, embriagados pelo poder do Poço da Eternidade, atenderam ao chamado do titã caído Sargeras e abriram um portal para a Legião Ardente.",
		full = "Há dez mil anos, os Altaneiros de Kalimdor, embriagados pelo poder do Poço da Eternidade, atenderam ao chamado do titã caído Sargeras e abriram um portal para a Legião Ardente. Malfurion Tempesfúria e a resistência kaldorei destruíram esse portal com a Alma Dragônica e lançaram Sargeras de volta à Espiral Etérea, mas o colapso do Poço partiu o próprio mundo. A antiga Kalimdor afundou em fogo e inundação; quatro continentes arruinados emergiram dos destroços, e o coração submerso da terra tornou-se o Grande Mar, com a Voragem revolvendo as águas onde antes ficava o Poço.",
		source = "https://warcraft.wiki.gg/wiki/Azeroth",
	},
	[1411] = {
		name = "Durotar",
		short = "Durotar é uma terra vermelha e rachada de penhascos e desfiladeiros, seca e quente, pobre em água e em verde.",
		full = "Durotar é uma terra vermelha e rachada de penhascos e desfiladeiros, seca e quente, pobre em água e em verde. Os orcs encontram nela uma beleza áspera que lembra Draenor, e foi aqui, depois do Monte Hyjal, que Thrall conduziu seu povo para construir um novo lar, batizando-o em homenagem ao pai assassinado, Durotan. A terra pertencia aos javatusco Crinavalha antes de a Horda expulsá-los.\n\nEssa paz não durou muito. O Grão-almirante Daelin Proudmore, herói da Segunda Guerra e nada amigo dos orcs, trouxe uma grande frota da Aliança contra Durotar, decidido a esmagar a Horda antes que ela criasse raízes. Sua filha Jaina escolheu outro caminho: em Theramore, ela se voltou contra o próprio pai para lutar ao lado de Thrall, e Daelin morreu na batalha antes que os dois pudessem se reconciliar. Em gratidão pela lealdade dela, Thrall permitiu que os soldados de Jaina se retirassem ilesos para Theramore.\n\nOs trolls Lançanegra chegaram à costa de Durotar como exilados, e não como colonos por escolha. Traídos por um dos seus, o feiticeiro Zalazane, foram expulsos de seu lar nas Ilhas do Eco e construíram a aldeia de pescadores de Sen'jin no litoral do continente, sem nunca conseguir recuperar o que Zalazane lhes tomara.",
		source = "https://warcraft.wiki.gg/wiki/Durotar_(Classic)",
	},
	[1412] = {
		name = "Mulgore",
		short = "Por centenas de anos, os taurens não tiveram terra própria, perseguidos por toda Kalimdor por saqueadores centauros que dispersaram suas tribos em acampamentos errantes.",
		full = "Por centenas de anos, os taurens não tiveram terra própria, perseguidos por toda Kalimdor por saqueadores centauros que dispersaram suas tribos em acampamentos errantes. Quando Thrall e seus orcs desembarcaram nestas terras, Caerne Casco Sangrento olhou para eles e viu espíritos afins, honrados e fortes. Com a escolta dos orcs e a força deles a seu lado, Caerne conduziu seu povo até o vale abrigado, cercado de montanhas por todos os lados, e ali sua tribo Casco Sangrento expulsou os centauros das pradarias e enfim as tomou para si.\n\nSobre a mesa que se erguia acima da planície, Caerne construiu o Penhasco do Trovão, um refúgio aberto a taurens de todas as tribos, e com o tempo os povos dispersos se uniram sob seu governo.\n\nOs pastos continuam verdes, as mesas ainda lançam suas longas sombras sobre a Aldeia Casco Sangrento, e todo tauren que chega à maioridade ainda precisa caminhar pelas planícies selvagens para provar seu valor na Grande Caçada, como fizeram seus ancestrais.",
		source = "https://warcraft.wiki.gg/wiki/Mulgore_(Classic)",
	},
	[1413] = {
		name = "Sertões",
		short = "A poeira daqui nem sempre foi poeira. Um dia isto foi floresta, cuidada pelos kaldorei que ergueram o posto avançado de Then'Ralore, e dizem que o semideus Lo'Gosh enfrentou aqui a Legião Ardente na Guerra dos Antigos.",
		full = "A poeira daqui nem sempre foi poeira. Um dia isto foi floresta, cuidada pelos kaldorei que ergueram o posto avançado de Then'Ralore, e dizem que o semideus Lo'Gosh enfrentou aqui a Legião Ardente na Guerra dos Antigos. A Grande Cisão pôs fim a tudo isso, e o vale verdejante se tornou a planície castigada pelo sol que é hoje.\n\nPor gerações, os taurens vagaram por estas planícies, caçando kodos e lagarto trovejante, buscando a sabedoria da Mãe Terra, sempre acossados por centauros que os caçavam por esporte. Eles revidavam, mas nunca por amor à guerra; quando os homens-cavalo chegavam, desmontavam suas tendas e seguiam adiante em vez de desperdiçar vidas. Um ano de paz, um ano de guerra: essa era a vida tauren, até que os orcs de Thrall e os trolls Lançanegra desembarcaram e marcharam com os taurens Casco Sangrento contra os centauros. Após a queda da Legião no Monte Hyjal, Thrall reivindicou a parte oriental dos Sertões, expulsou os javatusco Crinavalha e deu àquela terra o nome de Durotar, erguendo Orgrimmar como sua capital.\n\nA terra também guarda dores mais antigas: dizem que um homem chamado Dethorin encontrou sua amada Allurana nos braços de outro, e que seu grito arrancou da areia o machado Mataleija, a mesma lâmina que ele usou para matá-la.",
		source = "https://warcraft.wiki.gg/wiki/Barrens_(Classic)",
	},
	[1414] = {
		name = "Kalimdor",
		short = "Depois que a Cisão partiu o mundo, os elfos noturnos que restaram se isolaram deliberadamente do resto do mundo.",
		full = "Depois que a Cisão partiu o mundo, os elfos noturnos que restaram se isolaram deliberadamente do resto do mundo. Entre os humanos, Kalimdor sobreviveu apenas como lenda, uma terra que teria se partido e afundado sob as ondas, sem localização ou forma que eles conhecessem.\n\nMas ela não estava de todo perdida. Os elfos noturnos visitaram os quel'dorei nos anos que se seguiram, e assim apenas os elfos superiores de Quel'Thalas sabiam que a lenda era verdadeira.\n\nMesmo quando veio a Terceira Guerra, a maioria dos humanos ainda se recusava a acreditar que Kalimdor existia, e o próprio embaixador do Kirin Tor na corte do Rei Terenas estava entre os céticos. Apenas alguns deram ouvidos ao aviso de Medivh e navegaram para o oeste, entre eles a nova Horda de Thrall, seguida pela expedição de Jaina Proudmore. O que encontraram não era lenda, mas um continente inteiro, com gelo no norte, deserto no sul e elfos noturnos ainda guardando as matas entre um e outro.",
		source = "https://warcraft.wiki.gg/wiki/Kalimdor",
	},
	[1415] = {
		name = "Reinos do Leste",
		short = "Os Reinos do Leste nem sempre foram muitas terras.",
		full = "Os Reinos do Leste nem sempre foram muitas terras. Um dia, fizeram parte de um único continente, antes que a Grande Cisão dilacerasse o mundo e deixasse para trás os pedaços partidos hoje chamados de Azeroth, Khaz Modan e Lordaeron, com Quel'Thalas agarrada ao norte desta última terra despedaçada, incerta até hoje se é um lugar próprio ou apenas um canto de outro.\n\nPor esses fragmentos, as montanhas de Khaz Modan e de Cristarrubra se erguem como uma espinha dorsal pelo coração do continente, e ao redor delas os povos antigos resistem: anões e gnomos em seus salões profundos, humanos em seus reinos, altos elfos e elfos sangrentos em suas florestas, e agora os Renegados, erguidos onde antes vivia o povo de Lordaeron. Orcs, goblins, nagas e ogros também encontraram seu caminho até estas terras, embora nenhum deles tenha nascido nelas.\n\nAs cicatrizes daquela primeira ruptura ainda são a verdade deste lugar. Cada fronteira aqui, cada estreito e cada trecho de terra submersa entre um reino e outro, lembra que os Reinos do Leste já foram inteiros e não o são mais.",
		source = "https://warcraft.wiki.gg/wiki/Eastern_Kingdoms",
	},
	[1416] = {
		name = "Montanhas de Alterac",
		short = "A chuva nunca para completamente de cair sobre estes picos, e o céu acima deles é sempre cinzento.",
		full = "A chuva nunca para completamente de cair sobre estes picos, e o céu acima deles é sempre cinzento. Um dia, as montanhas coroaram a cidade-estado de Alterac, que dominava boa parte das terras do norte, e ainda abrigavam Dalaran. Alterac já não existe, e o que restou explica por que tão poucos ousam subir até aqui.\n\nQuando a Segunda Guerra terminou, a Aliança de Lordaeron descobriu que os senhores de Alterac haviam negociado em segredo com a Horda e enviou um exército a estas montanhas para golpear os traidores em seu próprio lar. A cidade caiu, seu povo foi disperso ou aprisionado, e sua linhagem nunca recuperou o trono. Um príncipe posterior daquela casa decaída, Aliden Perenolde, ergueu-se em vez disso como senhor dos bandidos, reunindo os proscritos e os vingativos na Camarilha, um bando de ladinos que ainda domina Strahnbrad e percorre estas encostas buscando recuperar o que sua família perdeu.\n\nHoje as ruínas da Cidade de Alterac pertencem aos ogros Massacrista, e a Camarilha domina boa parte do que os ogros não controlam.",
		source = "https://warcraft.wiki.gg/wiki/Alterac_Mountains_(Classic)",
	},
	[1417] = {
		name = "Planalto Arathi",
		short = "O Rei Thoradin veio a esta região árida porque um sonho lhe disse que seu povo prosperaria aqui, e sobre ela ergueu Strom, a primeira capital de uma Arathor unida.",
		full = "O Rei Thoradin veio a esta região árida porque um sonho lhe disse que seu povo prosperaria aqui, e sobre ela ergueu Strom, a primeira capital de uma Arathor unida. O solo seco lhe serviu de muralha de espinhos, negando aos trolls da floresta amani a cobertura para suas emboscadas, e ele ainda ergueu uma segunda muralha. Por mil anos, Strom esteve no coração do império, até que suas casas nobres partiram para solos mais ricos e os últimos descendentes de Thoradin foram embora para fundar Ventobravo. O que restou tornou-se Stromgarde, desde então governada pela linhagem Matatroll.\n\nStromgarde caiu desde então, tomada por ogros e pela Camarilha, e seus sobreviventes foram expulsos da bastilha para um desfiladeiro que hoje chamam de Ponta do Refúgio. Perto dali fica a Ruína do Martelo, antes um campo onde a humanidade enjaulava seus prisioneiros orcs, agora ocupado pelos próprios orcs e rebatizado em homenagem a Orgrim Martelo da Perdição.\n\nA grande muralha de Thoradin desmoronou numa ruína escancarada, e sua bastilha jaz destroçada e disputada, ainda alvo de lutas entre os ogros, a Camarilha e os últimos soldados de um reino que tenta retomá-la.",
		source = "https://warcraft.wiki.gg/wiki/Arathi_Highlands_(Classic)",
	},
	[1418] = {
		name = "Ermos",
		short = "Os Ermos são um deserto rachado de terra seca, rochedos espalhados e desfiladeiros sinuosos, cercado de montanhas por todos os lados.",
		full = "Os Ermos são um deserto rachado de terra seca, rochedos espalhados e desfiladeiros sinuosos, cercado de montanhas por todos os lados. Pouco sobrevive aqui além de coiotes, pumas e urubus.\n\nNos confins do norte ficam as ruínas de Uldaman, obra dos antigos terranos. Quando foi desenterrada, ofereceu as primeiras pistas sobre as elevadas origens dos anões, e garimpeiros de Altaforja chegaram em massa para vasculhar a ruína em busca de artefatos titânicos. Mas os trogg da Abóbada de Pedra, despertados após milênios de sono, massacraram os exploradores e agora defendem com fúria selvagem a cidade que roubaram. Uma grande fortaleza dos Ferro Negro fica logo ao sul de Uldaman, e seus anões guerreiam contra os ogros da tribo Arrota-pó e contra os dracos que se aninham entre as crias do dragão negro no leste.\n\nMais tarde, Karrath foi fundada aqui como o único posto avançado da Horda em Khaz Modan, erguido para que os orcs pudessem vigiar seus parentes renegados do clã Rocha Negra. O próprio Chefe Guerreiro Thrall enviou a Força Expedicionária de Karrath para caçar Laceral Mão Negra.",
		source = "https://warcraft.wiki.gg/wiki/Badlands_(Classic)",
	},
	[1419] = {
		name = "Barreira do Inferno",
		short = "A Barreira do Inferno faz jus ao nome. A argila vermelha sob os pés já foi terra parda, parte de um pântano sombrio chamado Lamaçal Negro, antes que a Horda orc abrisse aqui o Portal Negro e se despejasse sobre Azeroth.",
		full = "A Barreira do Inferno faz jus ao nome. A argila vermelha sob os pés já foi terra parda, parte de um pântano sombrio chamado Lamaçal Negro, antes que a Horda orc abrisse aqui o Portal Negro e se despejasse sobre Azeroth. A magia que vazou naquele dia queimou o solo até deixá-lo vermelho e o matou para sempre. Nada cresce aqui agora além de arbustos resistentes do deserto e criaturas resistentes do deserto: basiliscos, escorpiões, hienas.\n\nO Arquimago Khadgar e o Kirin Tor ergueram a Bastilha de Etergarde para vigiar as ruínas do portal e garantir que nada mais passasse por ele. A paz durou dois anos, até que a Horda de Draenor reabriu o Portal e sitiou a bastilha. Quando o ritual de Ner'zhul começou a despedaçar Draenor, Khadgar e os outros magos usaram o Crânio de Gul'dan para explodir em pedaços a moldura de pedra do Portal a partir do outro lado, cortando para sempre a ponte entre os mundos.\n\nHoje os magos e paladinos de Etergarde ainda mantêm sua vigília sombria sobre o Portal morto, uma comunidade fechada e sisuda que não confia em ninguém e não perdoa nenhum deslize, o único abrigo que se encontra numa terra onde as tempestades vindas do mar oriental escorrem pelo chão calcinado antes de fazer qualquer bem.",
		source = "https://warcraft.wiki.gg/wiki/Blasted_Lands_(Classic)",
	},
	[1420] = {
		name = "Clareiras de Tirisfal",
		short = "O céu sobre as Clareiras de Tirisfal paira num verde doentio há anos, e as árvores se agarram a qualquer vida que a praga lhes tenha deixado.",
		full = "O céu sobre as Clareiras de Tirisfal paira num verde doentio há anos, e as árvores se agarram a qualquer vida que a praga lhes tenha deixado. Um dia, aqui houve fazendas pacíficas sob o Rei Terenas, com gerações vivendo tranquilamente entre os moinhos e as plantações de abóbora. Tudo isso acabou quando Arthas Menethil saqueou Lordaeron e espalhou a praga pelos campos, matando seu povo e erguendo-o como escravo do Lich Rei. Valas comuns ainda marcam os lugares onde os mortos eram numerosos demais para serem enterrados como deveriam. Foi perto da Fazenda dos Balnir, meses depois, que Sylvana Correventos voltou suas banshees contra Arthas e cravou uma flecha envenenada no cavaleiro da morte antes que os esqueletos de Kel'Thuzad a repelissem.\n\nDessa ruína surgiram os Renegados, os mortos de livre-arbítrio de Sylvana, que tomaram a terra para si. Seus inimigos nunca a deixaram: a Cruzada Escarlate ocupa o antigo Monastério Escarlate no norte, fanáticos que queimam e caçam tudo o que não é humano.",
		source = "https://warcraft.wiki.gg/wiki/Tirisfal_Glades_(Classic)",
	},
	[1421] = {
		name = "Floresta de Pinhaprata",
		short = "A Floresta de Pinhaprata, ou simplesmente Pinhaprata, é um bosque vasto e antigo que se estende pelo acidentado litoral oeste de Lordaeron.",
		full = "A Floresta de Pinhaprata, ou simplesmente Pinhaprata, é um bosque vasto e antigo que se estende pelo acidentado litoral oeste de Lordaeron. O terreno varia de razoavelmente plano a montanhoso e fica aninhado entre montanhas ainda mais altas. A floresta tem um silêncio sinistro, quebrado apenas por algum uivo sobrenatural que ecoa entre as árvores de vez em quando. Saliências cobertas de musgo tremem na brisa fria, e as árvores estão todas doentes ou morrendo. Fazendas decrépitas e minas abandonadas pontilham a terra, agora lar dos habitantes mais sombrios da mata.\n\nEste bosque é assombrado e selvagem, marcado por seus pinheiros altos de casca prateada, que se elevam sobre outeiros cobertos de relva. A Aliança protegeu a Floresta de Pinhaprata quando ela era verdejante e cheia de vida. Agora o lugar está envolto em névoas fantasmagóricas. Os Renegados controlam o norte da floresta e entram em constante conflito com os miseráveis gnolls Putricouro. O que resta da população humana mantém o controle do sul da floresta, mas estão desesperados e suas forças, dispersas demais. Dalaran envia expedições frequentes a Pinhaprata para defender essas pessoas e estudar a praga dos mortos-vivos e a maldição worgen, uma aflição misteriosa que faz suas vítimas se transformarem em worgens licantropos sedentos de sangue quando a lua nasce.\n\nGuilnéas e o Contraforte de Eira dos Montes fazem fronteira com a floresta ao sul, enquanto as Clareiras de Tirisfal ficam ao norte. O Espelho de Lordaeron serve de fronteira leste de Pinhaprata.\n\nEmbora o território pertença aos Renegados, sua posse é disputada pelos magos de Dalaran e por agentes do Flagelo que se apossaram de alguns dos campos e sítios arruinados. Os gnolls Putricouro operam a partir da misteriosa Ilha de Fenris e atacam ferozmente quem ousa se aproximar de seus negócios. No sudoeste fica o Vilarejo Lenhardente, cujo povo caiu sob a maldição do arquimago Arugal e se transforma em worgens sedentos de sangue ao anoitecer. Arugal vive nas torres sombrias da vizinha Bastilha da Presa Negra.\n\nA Floresta de Pinhaprata é palco frequente de batalhas, pois forças da Aliança vindas de Costa Sul atravessam a mata desolada para atacar o Sepulcro ou entrar na Presa Negra. É a fronteira da pátria dos Renegados e o ponto mais ao sul onde os efeitos da praga dos mortos-vivos podem ser vistos na vegetação.",
		source = "https://warcraft.wiki.gg/wiki/Silverpine_Forest_(Classic)",
	},
	[1422] = {
		name = "Terras Pestilentas Ocidentais",
		short = "Estas já foram as terras agrícolas mais belas do norte de Lordaeron, arborizadas e verdes, abastecendo os celeiros do reino a partir de Andorhal e governadas do salão de Amparo.",
		full = "Estas já foram as terras agrícolas mais belas do norte de Lordaeron, arborizadas e verdes, abastecendo os celeiros do reino a partir de Andorhal e governadas do salão de Amparo. Essa prosperidade se tornou a arma usada para destruí-las.\n\nSeguindo o plano do Lich Rei, a Seita dos Malditos levou as energias de sua praga para o sul em caldeirões portáteis, escondendo-os em aldeias de cultistas leais e instalando os quatro maiores nos próprios campos de Andorhal. O próprio grão estava contaminado, e ele saiu por toda Lordaeron em carroças que ninguém pensou em questionar. As pessoas que comeram o próprio pão adoeceram, morreram e se ergueram de novo como escravas do Lich Rei. As florestas nunca se recuperaram. Os pinheiros estão cinzentos, com agulhas marrons, sob uma névoa doentia, e seus troncos, inchados de tumores.\n\nA ordem que resta foi recuperada após o colapso do reino, quando a Cruzada Escarlate tomou a Bastilha Mardenforte em Amparo e partiu dali contra os mortos-vivos que dominavam o resto da terra. Em meio a tudo isso, apenas um lugar mantém alguma paz: a Tumba de Uther, consagrada a Uther, o Arauto da Luz, um solo que a praga jamais tocou.",
		source = "https://warcraft.wiki.gg/wiki/Western_Plaguelands_(Classic)",
	},
	[1423] = {
		name = "Terras Pestilentas Orientais",
		short = "Este chão já foi terra de cultivo, com as aldeias do Leste espalhadas ao redor de Stratholme, a segunda cidade de Lordaeron. Nada disso resta.",
		full = "Este chão já foi terra de cultivo, com as aldeias do Leste espalhadas ao redor de Stratholme, a segunda cidade de Lordaeron. Nada disso resta. O solo agora é marrom e doente, as árvores incharam até virarem cogumelos, e o ar está carregado de uma névoa alaranjada.\n\nFoi a Stratholme que o Príncipe Arthas veio, caçando a origem de uma praga que já havia atingido os moradores da cidade. O Lorde Uther, mestre do Punho de Prata, recusou-se a deixá-lo expurgar a cidade. Arthas destituiu-o do comando, dissolveu o Punho de Prata ali mesmo e passou ele próprio o povo de Stratholme a fio de espada, em vez de deixá-lo se erguer como parte do Flagelo. E não parou por aí: perseguiu o senhor do medo Mal'Ganis até o norte, voltou como cavaleiro da morte e matou o próprio pai para pôr fim ao reino de Lordaeron.\n\nAlexandros Mograine ergueu uma Cruzada com o que restava do Punho de Prata para retomar a ruína, tomando a Manopla de Tyr e metade de Stratholme antes que sua morte dividisse a ordem entre a Aurora Argêntea e a Cruzada Escarlate, que ainda domina estes campos, guerreando contra o Flagelo sem fim e não acolhendo mais ninguém.",
		source = "https://warcraft.wiki.gg/wiki/Eastern_Plaguelands_(Classic)",
	},
	[1424] = {
		name = "Contraforte de Eira dos Montes",
		short = "O solo de Eira dos Montes é fértil e suas colinas são verdes, e os viajantes dizem que era assim que toda Lordaeron parecia antes da chegada da Praga.",
		full = "O solo de Eira dos Montes é fértil e suas colinas são verdes, e os viajantes dizem que era assim que toda Lordaeron parecia antes da chegada da Praga. Essa é tanto a sua crueldade quanto o seu consolo: a terra lembra o que foi perdido em todos os outros lugares, enquanto as pessoas que a ocupam travam a mesma guerra que arruinou o resto.\n\nNo início da Segunda Guerra, saqueadores orcs atacaram suas cidades costeiras, e o próprio Orgrim Martelo da Perdição marchou contra o Forte do Desterro para libertar Zul'jin de suas celas. Décadas depois, foi Thrall quem passou por estas colinas, reunindo os clãs orcs dispersos antes de se infiltrar em Costa Sul durante a noite para roubar seus navios e levar a nova Horda pelo mar até Kalimdor.\n\nO que os orcs começaram, os Renegados continuaram. Eles tomaram a Serraria Tarren como sua posse mais ao sul e a transformaram em base de operações contra os humanos de Costa Sul e dos Campos de Eira dos Montes, que se mantiveram firmes pela Aliança.\n\nBosques de pinheiros pontilham hoje as terras de cultivo, e estradas ainda cruzam os pastos rumo aos sombrios povoados dos Renegados ao norte, como se a própria terra ainda esperasse para ver qual lado ficará com ela.",
		source = "https://warcraft.wiki.gg/wiki/Hillsbrad_Foothills_(Classic)",
	},
	[1425] = {
		name = "Terras Agrestes",
		short = "Depois da Guerra dos Três Martelos, os anões Martelo Feroz abandonaram seus túneis em Grim Batol e vieram para o norte, construindo seus lares na superfície, no Ninho da Águia.",
		full = "Depois da Guerra dos Três Martelos, os anões Martelo Feroz abandonaram seus túneis em Grim Batol e vieram para o norte, construindo seus lares na superfície, no Ninho da Águia. Deixaram a pedra e a forja pelo céu e pelas asas, ligando-se aos grifos selvagens da região de forma tão estreita que ergueram um grande grifo de pedra em sua própria cidade para honrar esse vínculo. Os trolls da floresta que já ocupavam esta terra, remanescentes do outrora grandioso Império Amani, viam os anões como invasores de seu solo ancestral e atacavam os ninhais sempre que podiam.\n\nQuando a Horda avançou pela região durante a Segunda Guerra, o Thane Kurdran Martelo Feroz e seus cavaleiros, que até então nem sabiam da existência de tais invasores, caíram do céu sobre as colunas orcs com martelos carregados de tempestade, perseguindo-as sem trégua. Orgrim Martelo da Perdição esperava atrair as forças da Aliança para as Terras Agrestes para poder atacar Quel'Thalas sem oposição, mas Anduin Lothar percebeu o plano e cavalgou ele mesmo até o lado de Kurdran, e juntos derrotaram os invasores e os rechaçaram até as Montanhas de Alterac. Por isso, Kurdran prometeu a ajuda de seu povo à Aliança.",
		source = "https://warcraft.wiki.gg/wiki/Hinterlands_(Classic)",
	},
	[1426] = {
		name = "Dun Morogh",
		short = "A neve se acumula funda por toda Dun Morogh, cercada de todos os lados pelas montanhas de Khaz Modan, e seus desfiladeiros são sempre vigiados por tropas anãs.",
		full = "A neve se acumula funda por toda Dun Morogh, cercada de todos os lados pelas montanhas de Khaz Modan, e seus desfiladeiros são sempre vigiados por tropas anãs. Antes que as montanhas pertencessem a qualquer outro povo, pertenciam aos trolls do gelo Jubafria, que haviam se estabelecido na região depois de se separarem do Império Drakkari em eras passadas.\n\nIsso mudou quando os primeiros gnomos saíram de Uldaman e voltaram sua engenhosidade para sobreviver ao frio e aos trolls ao mesmo tempo, escavando moradias fortificadas nas profundezas dos picos. Quinhentos anos depois, os anões os seguiram para fora de Uldaman, atraídos pelas mesmas montanhas que tinham avistado no horizonte, e ergueram Altaforja sob a mais alta delas. Encontrando os gnomos já estabelecidos nas proximidades, os dois povos firmaram uma amizade que jamais se rompeu: os anões emprestaram sua força para erguer Gnomeregan, e os gnomos compartilharam os segredos de suas máquinas. Juntos, seus exércitos derrotaram os trolls Jubafria e rechaçaram os sobreviventes para as colinas, pondo fim para sempre ao domínio dos trolls sobre a terra.\n\nGnomeregan já não existe, está em ruínas, e seu povo se amontoa em Altaforja em busca de abrigo.",
		source = "https://warcraft.wiki.gg/wiki/Dun_Morogh_(Classic)",
	},
	[1427] = {
		name = "Garganta Abrasadora",
		short = "Um dia, esta foi uma terra verde, parte das Montanhas Cristarrubra, até que o próprio chão foi rasgado há mais de duzentos e trinta anos.",
		full = "Um dia, esta foi uma terra verde, parte das Montanhas Cristarrubra, até que o próprio chão foi rasgado há mais de duzentos e trinta anos.\n\nNa Guerra dos Três Martelos, o Thane-feiticeiro Thaurissan, dos anões Ferro Negro, buscou uma arma para aniquilar seus inimigos. Ele e sete de seus anões de maior confiança alcançaram as profundezas do mundo e invocaram poderes que deveriam ter continuado adormecidos. O que respondeu não foi um servo, mas um senhor: o antigo Senhor do Fogo Ragnaros. Seu despertar arrancou a Montanha Rocha Negra da terra, enegreceu o solo por quilômetros e esmagou sob ela a capital dos Ferro Negro, Thaurissan, reduzindo-a a escombros. As estepes calcinadas ao sul passaram a ser conhecidas como Estepes Ardentes; este vale devastado ao norte tornou-se a Garganta Abrasadora.\n\nNem todos os Ferro Negro permaneceram leais ao clã após a ruína. Alguns deles se separaram, chamando a si mesmos de Irmandade do Tório, e construíram o Posto de Tório, com vista para a grande escavação que seus antigos parentes abriram no fundo do vale, observando lá de cima o trabalho dos Ferro Negro.",
		source = "https://warcraft.wiki.gg/wiki/Searing_Gorge_(Classic)",
	},
	[1428] = {
		name = "Estepes Ardentes",
		short = "O céu sobre as Estepes Ardentes nunca perde o tom avermelhado, iluminado pelas erupções esporádicas da Montanha Rocha Negra, e o chão nunca esfria.",
		full = "O céu sobre as Estepes Ardentes nunca perde o tom avermelhado, iluminado pelas erupções esporádicas da Montanha Rocha Negra, e o chão nunca esfria. Duzentos anos antes da abertura do Portal Negro, os anões Ferro Negro vieram para cá exilados de Altaforja. Seu Thane-feiticeiro Thaurissan, tentou invocar lacaios elementais para vencer a Guerra dos Três Martelos contra os clãs Barbabronze e Martelo Feroz. O que respondeu não foi um lacaio, mas Ragnaros, o Senhor do Fogo, outrora banido pelos titãs. Sua chegada derreteu as montanhas ao seu redor, ergueu um vulcão no centro da explosão e destruiu os anões que o haviam invocado. O que ficava ao norte desse novo pico tornou-se a Garganta Abrasadora; o que ficava ao sul, as Estepes Ardentes, marcadas desde então.\n\nOs orcs se estabeleceram nas encostas do vulcão durante a Primeira Guerra e mantiveram o Pico da Rocha Negra como fortaleza durante a Segunda. Os orcs Rocha Negra voltaram depois e continuam lá até hoje, seguindo os velhos costumes brutais de antes da trégua de Thrall. Dragões negros sob o comando de Nefarian ocupam os níveis superiores do pico, e dizem que Ragnaros ainda remói sua ira em algum lugar abaixo de tudo isso.",
		source = "https://warcraft.wiki.gg/wiki/Burning_Steppes_(Classic)",
	},
	[1429] = {
		name = "Floresta de Elwynn",
		short = "Quando os orcs vieram na Primeira Guerra, milhares marcharam por Elwynn para cercar Ventobravo, isolando-a de tudo, exceto do mar.",
		full = "Quando os orcs vieram na Primeira Guerra, milhares marcharam por Elwynn para cercar Ventobravo, isolando-a de tudo, exceto do mar. O Cavaleiro Campeão Anduin Lothar liderou os Cavaleiros de Ventobravo numa carga pela própria floresta, atacando de surpresa a retaguarda orc e dispersando-a. Isso deu tempo à cidade, mas não o bastante. O Chefe Guerreiro Mão Negra logo tomou Vila d'Ouro e Arroio da Lua, as últimas cidades entre a Horda e o rei, e a Bastilha de Ventobravo foi saqueada. Lothar conduziu os sobreviventes até o mar e para longe, rumo a Lordaeron, e as ruínas da cidade pertenceram por um tempo ao clã Trovão Furioso. Catapultas orcs espalhadas ainda jazem quebradas e apodrecendo pela região, os únicos vestígios que restam daquela ocupação.\n\nOs Vinhedos de Vila Norte, a leste da cidade, já foram o orgulho dos fazendeiros de Ventobravo. Quando a Guilda dos Pedreiros ficou sem pagamento pelos anos que passou reconstruindo a capital arruinada, e os nobres a dissolveram em vez de quitar a dívida, a fúria do Mestre da Guilda Edwin VanCleef se espalhou em revoltas que mataram a Rainha Tiffin Ellerian Wrynn e deram origem à Irmandade Defias. A Irmandade expulsou os fazendeiros de Vila Norte e ocupou seus campos.",
		source = "https://warcraft.wiki.gg/wiki/Elwynn_Forest_(Classic)",
	},
	[1430] = {
		name = "Trilha do Vento Morto",
		short = "A Trilha do Vento Morto corta as montanhas do centro de Azeroth, ligando a Floresta do Crepúsculo ao Pântano das Mágoas. Há uns vinte anos, era considerada parte das Montanhas Cristarrubra.",
		full = "A Trilha do Vento Morto corta as montanhas do centro de Azeroth, ligando a Floresta do Crepúsculo ao Pântano das Mágoas. Há uns vinte anos, era considerada parte das Montanhas Cristarrubra.\n\nA Torre de Marfim de Karazhan, antiga sede do poder do mago sombrio Medivh, ergue-se no centro desta região escarpada e derrama magia maligna sobre a terra. As árvores estão petrificadas e sem folhas, e um vento terrível geme pelo desfiladeiro. Ogros, demônios, mortos-vivos e alguns ciganos humanos vagam pelo interior, e há quem sussurre que uma nova força tomou a Torre de Marfim e que os ogros e demônios estão sob seu domínio.",
		source = "https://warcraft.wiki.gg/wiki/Deadwind_Pass_(Classic)",
	},
	[1431] = {
		name = "Floresta do Crepúsculo",
		short = "Um manto de noite sobrenatural cobre a Floresta do Crepúsculo, e ele jamais se ergueu.",
		full = "Um manto de noite sobrenatural cobre a Floresta do Crepúsculo, e ele jamais se ergueu. O que antes era um belo trecho da Floresta de Elwynn é agora uma terra amaldiçoada e moribunda: as árvores cresceram retorcidas sob a névoa negra, os mortos se ergueram de suas covas e os worgens chegaram furtivos junto com a própria escuridão, atraídos pelas artes da Foice de Eluna. Os ogros que avançam a partir da Trilha do Vento Morto só aprofundaram a miséria.\n\nA proteção de Ventobravo há muito deixou de significar qualquer coisa aqui, e as pessoas que ficaram aprenderam a defender seu território sem ela. Sua milícia, a Vigília Noturna, patrulha as estradas e guarda Vila Sombria contra tudo o que se move nas sombras: guerreiros esqueléticos e carniçais, worgens ferozes e ainda homens da Defias.\n\nNo coração da mata fica a cratera de um vulcão extinto há muito tempo, envolta num crepúsculo mais suave que a escuridão ao redor. Ali se ergue uma das Grandes Árvores, com raízes que se estendem em direção ao Sonho Esmeralda, e a influência dos druidas adormecidos tinge tudo o que cresce nas proximidades. Além dela se estendem fazendas abandonadas e as vastas sepulturas do Cemitério de Monte Corvo, preenchidas ano após ano desde que a escuridão caiu.",
		source = "https://warcraft.wiki.gg/wiki/Duskwood_(Classic)",
	},
	[1432] = {
		name = "Loch Modan",
		short = "As águas de Loch Modan repousam num berço de pedra cinzenta, contidas pelo Dique Lapidado, uma obra da engenharia anã que nenhuma outra estrutura em Azeroth jamais igualou.",
		full = "As águas de Loch Modan repousam num berço de pedra cinzenta, contidas pelo Dique Lapidado, uma obra da engenharia anã que nenhuma outra estrutura em Azeroth jamais igualou. As montanhas se erguem íngremes por todos os lados, levemente arborizadas com pinheiros e bétulas, e o próprio lago permanece imóvel e silencioso, como se nada jamais o tivesse perturbado.\n\nO lago já foi um campo de batalha. Na Segunda Guerra, os orcs da Horda invadiram a região e fizeram aqui sua resistência contra a Aliança. Altaforja resistiu. Seus anões rechaçaram os orcs e retomaram Loch Modan, e os destroços daquela guerra nunca foram totalmente removidos: catapultas quebradas e balistas despedaçadas ainda jazem espalhadas pelo leito do lago e por suas ilhas, meio afundadas, a única prova que resta de que esta água calma já foi um campo de matança.",
		source = "https://warcraft.wiki.gg/wiki/Loch_Modan_(Classic)",
	},
	[1433] = {
		name = "Montanhas Cristarrubra",
		short = "As Montanhas Cristarrubra ficam a leste da Floresta de Elwynn, a nordeste da Floresta do Crepúsculo e ao sul das Estepes Ardentes.",
		full = "As Montanhas Cristarrubra ficam a leste da Floresta de Elwynn, a nordeste da Floresta do Crepúsculo e ao sul das Estepes Ardentes.\n\nRegião idílica de rios caudalosos, olmos altíssimos e terreno em aclive, Cristarrubra está sob a proteção de Ventobravo, embora desde a Segunda Guerra seja tecnicamente independente. Continua sendo uma das últimas regiões pacíficas de Azeroth, com um povo calmo e satisfeito que abastece Ventobravo de madeira, peixe e colheitas. Ainda assim, a paz é imperfeita: uma força de orcs Rocha Negra vinda das Estepes Ardentes ocupa a Bastilha Mirante de Pedra, embora até agora eles se mantenham reclusos. Comparada à ruína do Cerro Oeste, Cristarrubra ainda se mantém de pé.\n\nNa margem norte do Lago Plácido fica a cidade de Vila Plácida, sitiada por gnolls e orcs Rocha Negra vindos das colinas ao redor. Ao sul, a encruzilhada conhecida como Três Caminhos liga Vila Plácida a Elwynn e à Floresta do Crepúsculo, e pela Estrada Beira-lago à Bastilha Mirante de Pedra, uma estrada dominada por dragonetes, gnolls, murlocs e feras selvagens.\n\nA superfície do lago parece calma o bastante, mas murlocs espreitam sob ela, e persistem os boatos sobre um monstro marinho em suas profundezas.",
		source = "https://warcraft.wiki.gg/wiki/Redridge_Mountains_(Classic)",
	},
	[1434] = {
		name = "Selva do Espinhaço",
		short = "A Selva do Espinhaço é uma vasta selva ao sul da Floresta do Crepúsculo.",
		full = "A Selva do Espinhaço é uma vasta selva ao sul da Floresta do Crepúsculo. Trolls da selva patrulham esta floresta tropical abafada, e nagas caçam ao longo de seu litoral, enquanto as vinhas do espinhaço e as feras tornam a viagem perigosa.\n\nO vale já foi o coração do Império Gurubashi, cujas grandes cidades se espalhavam por toda a região. Após a queda do império, essas cidades desmoronaram em ruínas, embora os trolls ainda vivam entre elas. Zul'Gurub, no nordeste, foi um dia a capital Gurubashi.\n\nA Angra do Butim era originalmente uma pequena cidade portuária fundada por humanos, até ser tomada por trolls. Mais tarde, os goblins do Cartel Bondebico expulsaram os trolls da enseada e a tomaram para si, transformando-a em seu centro de operações nos Reinos do Leste.\n\nNo norte fica um complexo erguido pela expedição do Coronel Kurzen. Ali, a mente do coronel foi dominada por um ogro-mago, Mai'Zoth, que usou um artefato chamado Olho da Mente para dobrar a vontade de Kurzen e comandar seus homens. Alguns soldados de Kurzen se rebelaram contra o comandante possuído e fugiram para o oeste, fundando um acampamento rebelde em desafio a ele.",
		source = "https://warcraft.wiki.gg/wiki/Stranglethorn_Vale_(Classic)",
	},
	[1435] = {
		name = "Pântano das Mágoas",
		short = "Sob a água negra do pântano jaz um templo mais antigo que a mágoa que deu nome a este lugar.",
		full = "Sob a água negra do pântano jaz um templo mais antigo que a mágoa que deu nome a este lugar. Quando o Império Gurubashi caiu, um bando renegado de trolls chamado Atal'ai fugiu para o brejo e ergueu o Templo de Atal'Hakkar, onde praticava ritos macabros para trazer de volta ao mundo seu loa sombrio, Hakkar, o Esfolador de Almas. Sua magia distorceu as plantas e os animais ao redor do templo até que a corrupção não pudesse mais passar despercebida. Ysera, senhora dos sonhos, soube das ambições do culto e voltou seu poder contra eles, afundando o templo sob o maior dos lamaçais antes que Hakkar pudesse retornar. Mas ela não confiava que os trolls fossem abandonar seu deus para sempre. Designou seu consorte Erânicos e uma hoste de dragões verdes para manter vigília eterna sobre a ruína, para que ela nunca mais fosse usada para libertar tamanho mal sobre o mundo. Dracônidas verdes ainda patrulham estes pântanos sob seu comando, e o templo submerso continua selado sob a água, vigiado em vez de destruído.",
		source = "https://warcraft.wiki.gg/wiki/Swamp_of_Sorrows_(Classic)",
	},
	[1436] = {
		name = "Cerro Oeste",
		short = "O vento agora corre sem obstáculos pelos campos do Cerro Oeste, pois nada alto restou para detê-lo. Um dia, esta foi a despensa de Ventobravo, alimentando o jovem reino por gerações.",
		full = "O vento agora corre sem obstáculos pelos campos do Cerro Oeste, pois nada alto restou para detê-lo. Um dia, esta foi a despensa de Ventobravo, alimentando o jovem reino por gerações.\n\nQuando a Guilda dos Pedreiros ficou sem pagamento pela reconstrução de Ventobravo após a Segunda Guerra, e a guarda se voltou contra seus protestos, o Mestre da Guilda Edwin VanCleef levou seus homens a se esconder no campo em vez de enfrentar a justiça do Rei Varian. Ali eles se tornaram a Irmandade Defias, e sob um celeiro em Arroio da Lua, VanCleef encontrou uma antiga rede de minas profunda o bastante para esconder a construção de uma arma destinada a incendiar Ventobravo pelo mar. Ele expulsou os fazendeiros, contratou gnolls Pata Molhada para dominar a terra e mandou seus homens queimarem os campos e salgarem a terra para que nada voltasse a crescer ali.\n\nVentobravo, com os cofres vazios, deixou o Cerro Oeste à própria sorte. Apenas Miguel Mantoforte atendeu ao chamado, formando a Milícia do Povo no Morro da Sentinela quando nenhum exército veio.\n\nOs campos que ele salgou não perdoaram o Cerro Oeste por isso. O capim ainda cresce amarelo e ralo onde antes o trigo chegava à altura dos ombros.",
		source = "https://warcraft.wiki.gg/wiki/Westfall_(Classic)",
	},
	[1437] = {
		name = "Pantanal",
		short = "Um pântano frio e cinzento se estende abaixo da represa, com névoa sobre seus rios e lagoas, montanhas cercando-o por três lados e o mar aberto a oeste.",
		full = "Um pântano frio e cinzento se estende abaixo da represa, com névoa sobre seus rios e lagoas, montanhas cercando-o por três lados e o mar aberto a oeste. Escombros se espalham por ele, restos das fortalezas anãs que um dia dominaram este território. Agora murlocs, feras selvagens e orcs renegados o dominam, e o Porto de Menethil é o único ponto de apoio real da Aliança aqui.\n\nEsse porto nem sempre foi território da Aliança. Quando a Segunda Guerra começou, Orgrim Martelo da Perdição construiu sua frota de invasão numa pequena ilha na Baía de Baradin, para que seus navios pudessem atacar o litoral de Lordaeron sem enfrentar suas defesas terrestres. O Pantanal pagou por isso: orcs e dragões se alimentaram fartamente da terra, e a caça ficou escassa. Após a guerra, o porto foi reconstruído e rebatizado de Porto de Menethil, em homenagem a Terenas Menethil II.\n\nA queda de Grim Batol veio depois. A revoada dos dragões vermelhos, escravizada para servir ao clã Presa do Dragão ali, voltou-se contra seus captores assim que foi libertada, e o clã foi destroçado, com seus sobreviventes dispersos pelos ermos. Alexstrasza julgou ser um fardo de sua revoada manter a montanha selada, e desde então dracônicos vermelhos montam guarda sobre ela.",
		source = "https://warcraft.wiki.gg/wiki/Wetlands_(Classic)",
	},
	[1438] = {
		name = "Teldrassil",
		short = "Quando Malfurion Tempesfúria desapareceu no Sonho Esmeralda, o arquidruida Fandral Guenelmo assumiu a liderança do Círculo Cenariano em seu lugar e convenceu o Círculo dos Anciãos de que era chegada a hora de cultivar uma nova Árvore do Mundo e reconquistar a imortalidade que os elfos noturnos haviam perdido.",
		full = "Quando Malfurion Tempesfúria desapareceu no Sonho Esmeralda, o arquidruida Fandral Guenelmo assumiu a liderança do Círculo Cenariano em seu lugar e convenceu o Círculo dos Anciãos de que era chegada a hora de cultivar uma nova Árvore do Mundo e reconquistar a imortalidade que os elfos noturnos haviam perdido. No Mar Velado, eles ergueram Teldrassil, a coroa da terra, e construíram Darnassus em seus galhos. Mas Nozdormu, que havia abençoado a primeira Árvore do Mundo, recusou-se a abençoar esta, chamando o desejo de arrogante, e a imortalidade que os elfos noturnos buscavam nunca veio.\n\nCom o tempo, a terra no alto de Teldrassil caiu sob uma presença sinistra. Os pelursos e os grells de suas florestas enlouqueceram, sátiros surgiram entre as árvores, e as grandes tartarugas e os debulhadores que antes nadavam nas águas ao redor da árvore fugiram para encalhar e morrer nas praias da Costa Negra. A origem dessa corrupção continua um mistério, e Malfurion não retornou do Sonho para desvendá-la.",
		source = "https://warcraft.wiki.gg/wiki/Teldrassil_(Classic)",
	},
	[1439] = {
		name = "Costa Negra",
		short = "Uma névoa cinzenta cobre este litoral na maior parte do tempo, e os elfos noturnos há muito a consideram um aviso.",
		full = "Uma névoa cinzenta cobre este litoral na maior parte do tempo, e os elfos noturnos há muito a consideram um aviso. Chuva e rocha tornam a terra inóspita, e todas as tentativas de povoá-la além do entreposto comercial de Auberdine deram em nada.\n\nHá dez mil anos, as cidades gêmeas de Ameth'Aran e Bashal'Aran ficavam aqui, governadas por Athrikus Narassin. Quando a Guerra dos Antigos partiu o mundo e a Grande Cisão chegou, Athrikus jurou a seu povo que o salvaria. Ele cumpriu a letra da promessa e traiu seu espírito: prendeu as almas deles em gemas de alma, dizendo-lhes que aquilo era a vida eterna, enquanto na verdade os drenava para alimentar o próprio poder. As cidades caíram em ruínas, e o que caminha entre as pedras ali hoje não está de todo em paz.\n\nApós a Terceira Guerra, Fandral Guenelmo trouxe druidas do Círculo Cenariano para a Costa Negra e plantou uma nova Árvore do Mundo, Teldrassil, junto a este litoral.",
		source = "https://warcraft.wiki.gg/wiki/Darkshore_(Classic)",
	},
	[1440] = {
		name = "Vale Gris",
		short = "O Vale Gris é uma floresta ancestral, repleta de árvores antigas e magia antiga, e nunca deixou de ser disputado.",
		full = "O Vale Gris é uma floresta ancestral, repleta de árvores antigas e magia antiga, e nunca deixou de ser disputado.\n\nOs orcs do clã Brado Guerreiro vieram para cá primeiro como lenhadores. Goblins liderados por Neeloc Greedyfingers devastaram as árvores até que os pelursos locais os rechaçaram, e Grommash Grito Infernal, por sua vez, derrotou os pelursos e as Sentinelas para manter a ajuda dos goblins. O próprio Cenarius veio restaurar o que havia sido derrubado, e isso lhe custou a vida: os senhores da Legião Ardente transformaram sua confiança numa armadilha, e Grommash o abateu.\n\nCoisa pior veio quando a Legião marchou com força total sobre o Vale Gris. Os infernais de Archimonde caíram do céu em chamas, e mortos-vivos e demônios avançaram a partir do leste, sobrepujando os exércitos divididos de elfos noturnos, orcs e humanos antes de seguir rumo ao Monte Hyjal. Tyrande Murmuréolo despertou Malfurion do Sonho Esmeralda, e ele encontrou a floresta de que se lembrava consumida por fogo vil e por uma praga sufocante.\n\nEssa velha disputa nunca terminou. Os elfos noturnos ainda ocupam Astranaar e seus refúgios espalhados; a Horda avançou seus acampamentos Brado Guerreiro fundo no sul e no leste, cortando madeira e empurrando as Sentinelas para trás. Nenhum dos lados jamais encerrou a luta por estas matas.",
		source = "https://warcraft.wiki.gg/wiki/Ashenvale_(Classic)",
	},
	[1441] = {
		name = "Mil Agulhas",
		short = "O desfiladeiro é fundo e seco, com o leito perdido entre mesas imponentes, até que no leste se abre para a Chapada Cintilante, uma grande salina sob um céu amplo.",
		full = "O desfiladeiro é fundo e seco, com o leito perdido entre mesas imponentes, até que no leste se abre para a Chapada Cintilante, uma grande salina sob um céu amplo. O nascer do sol visto da Aldeia Vento Livre ou das alturas em torno do Pináculo da Nuvem Negra é um espetáculo sobre uma região tão árida. O druida Quentin já se perguntou se a secura implacável daqui, tão próxima da selva exuberante da vizinha Feralas, não seria algo nada natural, mas a marca de alguma magia estranha lançada sobre a terra.\n\nAs mesas altas pertencem aos taurens, e a Aldeia Vento Livre é seu reduto entre elas. Eles não mantiveram este território sem contestação. Os centauros locais os pressionavam e, pior ainda, seus próprios parentes da tribo Temível Totem se voltaram contra eles, de modo que os taurens da Aldeia Vento Livre foram forçados a lutar tribo contra tribo pelas terras altas. Só com a ajuda da Horda conseguiram rechaçar os centauros e os Temível Totem.",
		source = "https://warcraft.wiki.gg/wiki/Thousand_Needles_(Classic)",
	},
	[1442] = {
		name = "Cordilheira das Torres de Pedra",
		short = "O Morro das Torres de Pedra sempre pertenceu aos espíritos antes de pertencer a qualquer povo.",
		full = "O Morro das Torres de Pedra sempre pertenceu aos espíritos antes de pertencer a qualquer povo. Os elfos noturnos mantêm uma gruta e uma clareira em seu cume, em comunhão com a natureza, e os taurens também o consideram sagrado, pois foi aqui que o imortal Oráculo um dia observou os fios do destino enquanto a Mãe Terra os tecia. Diz a lenda que os primeiros taurens a se estabelecer nestas montanhas levaram totens flamejantes até os penhascos mais altos, acendendo fogueiras para An'she a fim de queimar a escuridão que se agarrava à pedra.\n\nMais abaixo na montanha, Eluna abençoou há muito tempo uma fonte com o dom da saúde. Mais tarde, harpias tomaram os picos próximos, capturando as mantícoras que ali se aninhavam e poluindo as águas da fonte. Thrall veio contra elas, com Caerne Casco Sangrento e seus taurens a seu lado, derrotando um bando de centauros para conquistar um Glifo de Purificação e limpar o que as harpias haviam corrompido. As mantícoras libertadas os levaram até o próprio Morro.\n\nEssa velha paz com a terra acabou no sul. A Empreendimentos S.A. devastou o Rochedo Cortavento, derrubando suas árvores, sufocando o ar com fuligem e poluindo a água com óleo e dejetos, até que os espíritos da montanha clamaram alto o bastante para que xamãs tão distantes quanto Orgrimmar os ouvissem.",
		source = "https://warcraft.wiki.gg/wiki/Stonetalon_Mountains_(Classic)",
	},
	[1443] = {
		name = "Desolação",
		short = "Theradras, filha de Therazane, a Mãe-pedra, um dia dormiu sob uma pradaria fértil.",
		full = "Theradras, filha de Therazane, a Mãe-pedra, um dia dormiu sob uma pradaria fértil. Xamãs taurens, acreditando que a própria Mãe Terra habitava lá embaixo, chamaram por ela durante décadas até que, enfim, algo respondeu: não a Mãe Terra, mas Theradras, despertada em fúria de seu sono. Ela se alimentou da terra para restaurar sua forma enfraquecida, e os prados morreram num instante. Os taurens deram ao que restou o nome de Desolação.\n\nZaetar, filho do senhor da floresta Cenarius, veio para aprisioná-la, mas em vez disso a amou, e ela o amou também. Dessa união nasceram os centauros, e seu primeiro ato foi assassinar o próprio pai. Eles se multiplicaram rapidamente e expulsaram os taurens da terra, dando início a séculos de guerra entre as duas raças.\n\nTheradras ainda habita Maraudon, sob os desfiladeiros do oeste, e é lá que os centauros situam o nascimento de sua raça.",
		source = "https://warcraft.wiki.gg/wiki/Desolace_(Classic)",
	},
	[1444] = {
		name = "Feralas",
		short = "Feralas surge estranha entre seus vizinhos, uma floresta tropical de árvores antigas onde os ermos ao redor só prometem poeira.",
		full = "Feralas surge estranha entre seus vizinhos, uma floresta tropical de árvores antigas onde os ermos ao redor só prometem poeira. Espalhadas por seu verde estão as ruínas dos elfos, meio engolidas por raízes e vinhas, e a maior delas é a cidade soterrada de Gládio Cruel.\n\nOs ogros Gordunni dominam Feralas agora, e a tornaram sua destruindo-a. Derrubaram trechos inteiros de floresta, e sua mácula se instalou sobre a terra como uma doença. Além das muralhas de Gládio Cruel, seus grupos de saque incendeiam aldeias e matam viajantes pelas matas do sul, uma corrupção que se espalha pelos ermos e remonta às ruínas lá embaixo.\n\nOs taurens Temível Totem ainda vivem espalhados pela região, caçados por aqueles que se lembram do que a tribo fez.",
		source = "https://warcraft.wiki.gg/wiki/Feralas_(Classic)",
	},
	[1445] = {
		name = "Pântano Vadeoso",
		short = "Os mosquitos nunca param por aqui, e a lama também não.",
		full = "Os mosquitos nunca param por aqui, e a lama também não. As árvores entrelaçam suas folhagens com tanta densidade sobre a água que a luz do sol chega em pedaços, e crocoliscos e murlocs esperam nos baixios salobros onde o mar encontra o pântano. No sul, dragões negros se reúnem em tamanho número que as pessoas simplesmente chamam o lugar de Pântano da Serpe.\n\nJaina Proudmore fez o primeiro verdadeiro lar nesta região selvagem, trazendo seu povo para cá depois da batalha no Monte Hyjal para fundar Theramore em sua ilha rochosa. As muralhas de sua cidade reluzem, mas também a confinam: além dos postos de controle espalhados pela estrada para os Sertões, o pântano continua tão selvagem quanto sempre, e sua guarnição vem minguando com deserções silenciosas que ninguém consegue explicar.\n\nFoi aqui também que a paz entre a Horda e a Aliança se rompeu de vez. O Grão-Almirante Daelin Proudmore trouxe a frota de Kul Tiraz contra a Horda no pântano, e a escaramuça que se seguiu terminou com sua morte, transformando a trégua em inimizade declarada.\n\nA Aldeia Muralha Verde fica onde os ogros Pedramalho abriram seus portões para a Horda. Além dela, a estrada para os Sertões está vazia e caindo aos pedaços, vigiada apenas pelos raptores e aranhas que sempre foram donos deste território.",
		source = "https://warcraft.wiki.gg/wiki/Dustwallow_Marsh_(Classic)",
	},
	[1446] = {
		name = "Tanaris",
		short = "A areia preenche o lugar onde antes havia uma selva. Antes de o mundo se partir, Tanaris era verde, reivindicada como território pelo Império Gurubashi.",
		full = "A areia preenche o lugar onde antes havia uma selva. Antes de o mundo se partir, Tanaris era verde, reivindicada como território pelo Império Gurubashi. Quando a Grande Cisão dilacerou a terra, a selva morreu e o que restou se calcinou em dunas e pedras. Uma tribo de trolls ficou isolada aqui quando as águas recuaram e, ao longo dos muitos anos que se seguiram, seus corpos e seus costumes se curvaram ao deserto até que deixaram de ser os trolls que haviam sido e se tornaram trolls da areia, os Zangareia, um povo moldado pela terra que os aprisionou.\n\nOs goblins do Cartel Bondebico escolheram esta terra desolada para seu comércio, fundando Geringontzan e o Porto de Bondebico porque o deserto é o mais próximo de sua terra natal submersa que Kalimdor lhes permite colonizar. As docas de Bondebico se estendem em direção às ilhas mais além, mas os goblins guardam seus navios para si, sem disposição para levar qualquer outra raça pelo mar.\n\nSob as dunas e as montanhas do sul, os túneis se estendem por quilômetros, em grande parte inexplorados, e quem desce até lá nem sempre volta para contar o que encontrou.",
		source = "https://warcraft.wiki.gg/wiki/Tanaris_(Classic)",
	},
	[1447] = {
		name = "Azshara",
		short = "O outono domina Azshara há dez mil anos, com suas árvores ardendo em laranja e vermelho sobre penhascos que despencam em corais onde uma cidade ainda jaz.",
		full = "O outono domina Azshara há dez mil anos, com suas árvores ardendo em laranja e vermelho sobre penhascos que despencam em corais onde uma cidade ainda jaz. Azshara já foi a maior metrópole que os elfos noturnos ergueram, e quando veio a Guerra dos Antigos, a maior parte dela foi parar no mar. Algumas construções destroçadas ainda se agarram à encosta do penhasco, contemplando lá de cima suas próprias ruínas sob a água.\n\nMuito tempo depois, quando Illidan Tempesfúria fugiu para o norte a partir do Monte Hyjal com seus nagas, mur'guls e sátiros a reboque, ele devastou a costa de Azshara, destruindo os portos dos elfos noturnos para que ninguém pudesse segui-lo até a Tumba de Sargeras. Maiev Cantonegro e suas Vigias vieram atrás dele, abatendo as criaturas enlouquecidas que ele deixava pelo caminho.",
		source = "https://warcraft.wiki.gg/wiki/Azshara_(Classic)",
	},
	[1448] = {
		name = "Selva Maleva",
		short = "As árvores da Selva Maleva não crescem, e sim apodrecem. Sua casca verte um icor doentio, suas folhas pendem negras e enroladas, e os animais sob elas surgem retorcidos e famintos por causa da corrupção no solo.",
		full = "As árvores da Selva Maleva não crescem, e sim apodrecem. Sua casca verte um icor doentio, suas folhas pendem negras e enroladas, e os animais sob elas surgem retorcidos e famintos por causa da corrupção no solo.\n\nA podridão não foi um acidente da natureza. Enquanto a Legião Ardente avançava rumo ao Monte Hyjal, Archimonde ordenou que a floresta fosse destruída para enfraquecer os elfos noturnos que guardavam a montanha, e o senhor do medo Taecondrius cumpriu essa ordem com uma relíquia bruxa de terrível poder, o Crânio de Gul'dan. A terra reagiu morrendo de dentro para fora: os anciões se tornaram podres e violentos, as feras sofreram mutações e a própria terra foi envenenada.\n\nFoi aqui que Illidan Tempesfúria fez a escolha que moldou o resto de sua vida. Informado de que o crânio podia ser usado contra a própria corrupção que havia causado, Illidan entrou sozinho na Selva Maleva, abateu Taecondrius e tomou a relíquia para si. E não a entregou depois. Sua fome de magia se mostrou mais forte que a cautela e, por usar o próprio poder da Legião, ele foi banido pelo próprio irmão, Malfurion.",
		source = "https://warcraft.wiki.gg/wiki/Felwood_(Classic)",
	},
	[1449] = {
		name = "Cratera Un'Goro",
		short = "A Cratera Un'Goro fica isolada entre três desertos, uma ferida verde afundada no sul de Kalimdor, onde o mundo se esquece de ser árido.",
		full = "A Cratera Un'Goro fica isolada entre três desertos, uma ferida verde afundada no sul de Kalimdor, onde o mundo se esquece de ser árido. Dinossauros mais antigos que a memória percorrem sua selva, alguns crescidos a tamanhos que nenhum ser vivo deveria atingir, e elementais de terra e de fogo caminham tranquilamente entre eles. Nas cristas acima, erguem-se pilares que ninguém jamais explicou.\n\nDurante a Guerra das Areias Cambiantes, os elfos noturnos foram rechaçados através desta cratera até a borda do deserto de Tanaris, e ali o avanço qiraji foi contido. Algo na própria Un'Goro não permitiu que os invasores tomassem a terra, embora ninguém tenha dito o quê.\n\nUma expedição liderada por Williden e Hol'anyee Marshal tentou certa vez estabelecer um ponto de apoio aqui, mas a selvageria da cratera se mostrou maior do que eles estavam preparados para enfrentar. Seus acampamentos foram tomados, e os sobreviventes fugiram para terras mais altas, resistindo no lugar hoje chamado Refúgio do Marshal.",
		source = "https://warcraft.wiki.gg/wiki/Un'Goro_Crater_(Classic)",
	},
	[1450] = {
		name = "Clareira da Lua",
		short = "A Clareira da Lua repousa aninhada num anel de montanhas, um vale oculto onde a floresta nunca conheceu a corrupção.",
		full = "A Clareira da Lua repousa aninhada num anel de montanhas, um vale oculto onde a floresta nunca conheceu a corrupção. Em seu coração fica o Lago Eluna'ara, batizado em homenagem à própria deusa, e na cidade de Refúgio Noturno, às suas margens, taurens e elfos noturnos convivem sem desavenças, unidos por uma reverência comum à natureza que os Guardiões da Clareira da Lua não deixarão ser rompida.\n\nFoi a este vale que Malfurion Tempesfúria veio nos dias da Guerra dos Antigos, quando os elfos noturnos estavam à beira da ruína diante da Legião. Malfurion sabia que seu povo não venceria sozinho, e levou Tyrande Murmuréolo e seu irmão Illidan à quietude sagrada da Clareira da Lua para implorar a ajuda de Cenarius. O semideus atendeu e, depois que a Grande Cisão remodelou o mundo, os guardiões do bosque e as dríades que haviam se abrigado aqui partiram mundo afora. O próprio Cenarius nunca partiu, e a Clareira da Lua se tornou o solo mais sagrado do culto druídico.\n\nSob seus incontáveis montes dormem os santuários de druidas do passado, e sob as águas de Eluna'ara dorme o semideus Omen, outrora amado de Eluna, em um sono inquieto.",
		source = "https://warcraft.wiki.gg/wiki/Moonglade",
	},
	[1451] = {
		name = "Silithus",
		short = "O deserto fica no extremo sudoeste de Kalimdor, uma vastidão de rocha partida e areia alcançada pelo largo caminho que sai de Un'Goro.",
		full = "O deserto fica no extremo sudoeste de Kalimdor, uma vastidão de rocha partida e areia alcançada pelo largo caminho que sai de Un'Goro. Sob sua superfície jaz o que restou do império aqir, Ahn'Qiraj, cujo templo central os elfos noturnos selaram na tentativa de impedir que algo terrível despertasse. As ruínas espalhadas por Silithus e as colmeias silitídeas que agora crivam a areia são prova suficiente de que o selo não resistiu.\n\nHá muito tempo, os próprios qirajis foram rechaçados para trás da Muralha do Escaravelho e aprisionados ali após a Guerra das Areias Cambiantes. Seus servos, os silitídeos, ficaram livres e, ao longo dos séculos, multiplicaram-se e espalharam-se por todo o sul de Kalimdor, até que os elfos noturnos julgaram a ameaça grande demais para apenas observá-la e decidiram, em vez disso, reabrir os Portões de Ahn'Qiraj para terminar o que a Muralha apenas adiara.\n\nO Círculo Cenariano mantém sua vigília a partir do Forte Cenariano, rastreando os enxames silitídeos e avaliando se eles são um perigo grande demais para qualquer povo enfrentar sozinho.",
		source = "https://warcraft.wiki.gg/wiki/Silithus_(Classic)",
	},
	[1452] = {
		name = "Hibérnia",
		short = "A neve se estende intocada por Hibérnia, e sua beleza permanece imperturbada mesmo onde demônios tomaram as regiões do sul. Um dia, ela foi o lar de muitos membros da revoada azul, entre eles Haleh, consorte de Malygos.",
		full = "A neve se estende intocada por Hibérnia, e sua beleza permanece imperturbada mesmo onde demônios tomaram as regiões do sul. Um dia, ela foi o lar de muitos membros da revoada azul, entre eles Haleh, consorte de Malygos.\n\nHá dez mil anos, os Altaneiros ergueram aqui a cidade de Kel'Theril, depois de roubar o Cristal de Zin-Malor de um templo em Eldarath. Não conseguiram resistir a testar seu poder e, quando ele se despedaçou, a maldição que libertou os devorou. A Grande Cisão terminou o que o cristal começara, e Kel'Theril caiu em ruínas. Seus mortos nunca partiram. Mais tarde, elfos superiores vieram de Quel'Thalas em busca dos fragmentos do cristal, e a mesma loucura os tomou. Agora seus fantasmas vagam pelas ruínas ao lado daqueles que vieram estudar.\n\nOs goblins dominam Visteterna, no coração do vale, e os elfos noturnos ainda mantêm sua própria vigília aqui, guardando uma pátria mais antiga que ambos.",
		source = "https://warcraft.wiki.gg/wiki/Winterspring_(Classic)",
	},
	[1453] = {
		name = "Ventobravo",
		short = "Ventobravo se ergueu em pedra branca depois que a Horda orc a incendiou, reconstruída pela Guilda dos Pedreiros sob o jovem Rei Varian.",
		full = "Ventobravo se ergueu em pedra branca depois que a Horda orc a incendiou, reconstruída pela Guilda dos Pedreiros sob o jovem Rei Varian. Mas quando os cofres da coroa se esgotaram com as dívidas de guerra e a nobreza negou à guilda seus salários, o protesto do Mestre da Guilda Edwin VanCleef foi respondido com a dissolução da guilda. Seguiram-se revoltas, e no caos a Rainha Tiffin Wrynn foi morta. A ira de Varian levou os pedreiros ao exílio no Cerro Oeste, onde se tornaram a Irmandade Defias, enquanto, por trás do trono, uma conselheira chamada Katrana Prestor discretamente jogava o rei contra a guilda para atender aos próprios fins.\n\nDesde então, o Rei Varian desapareceu em circunstâncias suspeitas e, por insistência de Lady Prestor, a coroa foi entregue a seu jovem filho, o Príncipe Anduin, para preservar a ordem no reino. O Grão-lorde Bolvar Fordragon atua como Regente de Ventobravo e comandante de suas forças, enquanto Lady Prestor o aconselha sobre o uso dos recursos do reino, sem despertar suspeitas nem sofrer contestação dentro da Bastilha.",
		source = "https://warcraft.wiki.gg/wiki/Stormwind_City",
	},
	[1454] = {
		name = "Orgrimmar",
		short = "Orgrimmar se ergueu nos anos que se seguiram ao Monte Hyjal, quando o Chefe Guerreiro Thrall conduziu seu povo a um litoral desolado de Kalimdor.",
		full = "Orgrimmar se ergueu nos anos que se seguiram ao Monte Hyjal, quando o Chefe Guerreiro Thrall conduziu seu povo a um litoral desolado de Kalimdor. Ele deu à terra o nome de Durotar, em homenagem ao pai, e à cidade que ali ergueu deu o nome de Orgrimmar, em honra a Orgrim Martelo da Perdição, o amigo e mentor que o havia formado. Foi construída depressa, mas não sem cuidado: muralhas robustas, portões maciços, torres altas, e as montanhas às suas costas foram escavadas para formar parte da própria fortaleza, de modo que a terra montasse guarda sobre a cidade.\n\nA Horda que a construiu não era a Horda que um dia havia incendiado o mundo. Rompida a maldição demoníaca, o povo de Thrall trocou a conquista pela sobrevivência, e Orgrimmar foi erguida tanto por outros quanto por orcs: goblins, taurens e trolls Lançanegra trabalharam lado a lado com eles, e o mok'nathal Rexxar deu sua contribuição à obra. Centauros, harpias, lagartos trovejantes, kobolds e javatuscos puseram à prova a jovem cidade em seus primeiros anos, mas ela resistiu e se tornou lar não só dos orcs, mas também de trolls, taurens e, com o tempo, dos Renegados, recém-acolhidos na Horda.\n\nO próprio vento não é amigo aqui: os ventos cortantes varrem os vales com força suficiente para arrancar o telhado de construções erguidas sem cuidado.",
		source = "https://warcraft.wiki.gg/wiki/Orgrimmar",
	},
	[1455] = {
		name = "Altaforja",
		short = "Altaforja é a capital dos anões, escavada nas profundezas da Montanha de Altaforja, no norte de Dun Morogh, lar ancestral dos anões e uma das cidades mais antigas de Azeroth.",
		full = "Altaforja é a capital dos anões, escavada nas profundezas da Montanha de Altaforja, no norte de Dun Morogh, lar ancestral dos anões e uma das cidades mais antigas de Azeroth. É a capital de Khaz Modan, governada pelo Rei Magni Barbabronze, do clã Barbabronze.\n\nUma vasta cidade subterrânea de artesãos, exploradores, mineiros e guerreiros, famosa por sua indústria e como centro comercial da Aliança, Altaforja é em igual medida fortaleza e capital, um testemunho da força e da resiliência dos anões. A cidade é formada por anéis concêntricos, com níveis menores mais fundo no subsolo, todos irradiando a partir da Grande Forja que lhe dá nome, em seu centro. É repleta de pequenas passagens, lojas construídas nas paredes de rocha e salões cavernosos. O clima do lugar é agitado, barulhento e industrial, mas aconchegante; fogueiras crepitam nas lareiras das estalagens e lojas, e ouve-se muita risada e folia anã. Ao contrário de Ventobravo e Darnassus, a cidade é uma enorme caverna escavada na terra pelos próprios anões; o teto e o chão são ambos de pedra dura.",
		source = "https://warcraft.wiki.gg/wiki/Ironforge",
	},
	[1456] = {
		name = "Penhasco do Trovão",
		short = "O Penhasco do Trovão se ergue sobre quatro mesas varridas pelo vento acima das pradarias de Mulgore, acessível apenas por elevadores de corda e madeira de fabricação tauren ou por longas pontes estendidas entre as elevações.",
		full = "O Penhasco do Trovão se ergue sobre quatro mesas varridas pelo vento acima das pradarias de Mulgore, acessível apenas por elevadores de corda e madeira de fabricação tauren ou por longas pontes estendidas entre as elevações. Tendas, casas compridas e totens pintados coroam cada cume. Por gerações, os taurens vagaram como um povo nômade, acossados sem descanso pelos centauros que percorriam Kalimdor. Foi Caerne Casco Sangrento, chefe da tribo Casco Sangrento, quem pôs fim a esse exílio. Quando o Chefe Guerreiro Thrall e sua Nova Horda chegaram a Mulgore durante a Terceira Guerra, a força deles se uniu à de Caerne e, juntos, derrotaram os centauros e enfim conquistaram as pradarias para os taurens. Sobre as mesas, Caerne ergueu um refúgio aberto a todas as tribos dispersas e, com o tempo, essas tribos se curvaram a seu governo como um só povo, às vezes discordando sobre o caminho a seguir, mas nunca sobre sua sabedoria para liderá-los.\n\nOs penhascos ainda carregam o peso dessa fundação em suas elevações e pontes, nas tendas das tribos reunidas sob o teto de um só chefe.",
		source = "https://warcraft.wiki.gg/wiki/Thunder_Bluff",
	},
	[1457] = {
		name = "Darnassus",
		short = "Os elfos noturnos construíram Darnassus depois da Terceira Guerra, quando sua longa imortalidade os abandonou. Muitos não suportaram o peso repentino do envelhecimento e da fragilidade.",
		full = "Os elfos noturnos construíram Darnassus depois da Terceira Guerra, quando sua longa imortalidade os abandonou. Muitos não suportaram o peso repentino do envelhecimento e da fragilidade. Alguns druidas enlutados resolveram plantar uma nova Árvore do Mundo para restaurar seu vínculo com o mundo eterno. Com o desaparecimento de Malfurion Tempesfúria, Fandral Guenelmo assumiu o manto de Arquidruida e liderou o esforço. A árvore que ergueram, Teldrassil, elevou-se ao largo da costa até sua copa romper as nuvens, e entre seus galhos os elfos noturnos fundaram sua cidade como testemunho da sobrevivência de seu povo.\n\nDarnassus é aberta para o céu, ao contrário das cidades fechadas e muradas dos humanos e dos anões. Foi construída ao redor de um amplo lago, com margens unidas por pontes graciosas e caminhos atapetados de folhas caídas. O Templo da Lua se ergue acima das árvores como sede da Suma Sacerdotisa Tyrande Murmuréolo e de suas Irmãs de Eluna, ao lado do Salão da Justiça, cercado de colunatas, onde as Sentinelas mantêm sua vigília. A cidade continua sendo aquilo para que foi construída: um refúgio tranquilo e um monumento a um povo que aprende a viver com a mortalidade.",
		source = "https://warcraft.wiki.gg/wiki/Darnassus",
	},
	[1458] = {
		name = "Cidade Baixa",
		short = "Muito antes de os Renegados a tomarem para si, a Cidade Baixa tinha um nome e um propósito. Bem abaixo do palácio de Lordaeron se estendiam as antigas criptas de seus mortos reais, suas masmorras, seus esgotos.",
		full = "Muito antes de os Renegados a tomarem para si, a Cidade Baixa tinha um nome e um propósito. Bem abaixo do palácio de Lordaeron se estendiam as antigas criptas de seus mortos reais, suas masmorras, seus esgotos. Destinava-se apenas a prisioneiros e cadáveres, mas os mais pobres do povo de Lordaeron desciam em massa para a escuridão mesmo assim, e as varreduras dos guardas para expulsá-los nunca funcionavam.\n\nQuando o domínio do Lich Rei sobre suas criações enfraqueceu, Sylvana Correventos rompeu com o Flagelo levando os mortos-vivos que haviam mantido a mente e voltou-se contra Arthas, o príncipe caído que a havia transformado no que era. Ela o atraiu para uma armadilha no reino arruinado; ele escapou com a ajuda de Kel'Thuzad e fugiu para o norte para se tornar ele mesmo o Lich Rei. Sylvana e seus seguidores, senhores do campo de batalha, passaram a se chamar Renegados e tomaram as criptas sob a capital destroçada, concluindo a fortaleza que o Flagelo havia começado.\n\nO que existe hoje é um labirinto construído para a defesa: rios de lodo venenoso correm por todas as avenidas, e o ar é tão carregado de vapores que os vivos mal suportam respirá-lo. Para os Renegados, é um abrigo num mundo que ainda os caça.",
		source = "https://warcraft.wiki.gg/wiki/Undercity",
	},
}

